import json, sys, io
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

wb = load_workbook(
    r"c:\Users\016551\OneDrive\Desktop\流程建设\说明书重复校对需求-丹丹\测试文件\1.【THK产品信息包】THK GTM文件from产品(241101).xlsx",
    read_only=False, data_only=True
)

lines = []
for ws in wb.worksheets:
    if "Product Info" in ws.title and "红色" in ws.title:
        lines.append(f"SHEET: {ws.title} | rows={ws.max_row} cols={ws.max_column}")
        max_r = min(ws.max_row or 0, 80)
        max_c = min(ws.max_column or 0, 10)
        for row_idx in range(1, max_r + 1):
            vals = {}
            has = False
            for col_idx in range(1, max_c + 1):
                v = ws.cell(row=row_idx, column=col_idx).value
                if v is not None:
                    v = str(v).replace("\r", " ").replace("\n", " ").strip()
                    if len(v) > 500:
                        v = v[:500] + "..."
                    has = True
                    vals[get_column_letter(col_idx)] = v
            if has:
                lines.append(f"ROW {row_idx}: {json.dumps(vals, ensure_ascii=False)}")

with open(r"c:\Users\016551\OneDrive\Desktop\baseline2_content.txt", "w", encoding="utf-8") as f:
    f.write("\n".join(lines))
